const TZ = 'Asia/Ho_Chi_Minh';
// The NocoDB node nests a row as { id, id_fields, fields }.
const rowsOf = (name) => $(name).all()
  .map((i) => i.json || {})
  .filter((j) => j.id !== undefined && j.id !== null)
  .map((j) => ({ Id: j.id, ...(j.fields || {}) }));
const settingsOf = (name) => Object.fromEntries(
  rowsOf(name).filter((r) => r.key).map((r) => [r.key, (r.value ?? '').toString().trim()]));
const parseDt = (s) => DateTime.fromISO(String(s || '').trim().replace(' ', 'T'), { setZone: true }).setZone(TZ);
const parseDate = (s) => DateTime.fromISO(String(s || '').trim().slice(0, 10), { zone: TZ });
// settings.post_window, e.g. "07:00-22:00": the times posts may go out.
const windowOf = (v) => {
  const m = String(v || '').match(/(\d{1,2}):(\d{2})\s*-\s*(\d{1,2}):(\d{2})/);
  return m ? { from: `${m[1].padStart(2, '0')}:${m[2]}`, to: `${m[3].padStart(2, '0')}:${m[4]}` } : { from: '07:00', to: '22:00' };
};
const validTime = (t) => /^([01]\d|2[0-3]):[0-5]\d$/.test(t);
const slotOf = (dt) => { const h = Math.floor(dt.hour / 3) * 3; return `${String(h).padStart(2, '0')}-${String(h + 3).padStart(2, '0')}h`; };

const settings = settingsOf('Load settings');
const docs = (settings.brand_doc_urls || '')
  .split(/\s+/)
  .map((u) => u.trim())
  .filter(Boolean)
  .map((url) => {
    const m = url.match(/\/(wiki|docx|docs)\/([A-Za-z0-9]+)/);
    return m ? { url, kind: m[1] === 'wiki' ? 'wiki' : 'docx', token: m[2] } : { url, kind: 'unknown', token: '' };
  });
return [{ json: { settings, docs, has_docs: docs.some((d) => d.kind !== 'unknown') } }];

const token = $json.tenant_access_token;
if (!token) throw new Error('No Lark tenant token: ' + JSON.stringify($json).slice(0, 300));
return $('Read settings').first().json.docs
  .filter((d) => d.kind !== 'unknown')
  .map((d) => ({
    json: {
      ...d,
      auth: token,
      resolve_url: d.kind === 'wiki'
        ? `https://open.larksuite.com/open-apis/wiki/v2/spaces/get_node?token=${d.token}`
        : `https://open.larksuite.com/open-apis/docx/v1/documents/${d.token}`,
    },
  }));

// A wiki link points at a node; the document behind it is node.obj_token.
const requests = $('Doc requests').all();
return $input.all().map((item, i) => {
  const req = requests[i].json;
  const r = item.json || {};
  const data = r.data || {};
  let docId = '';
  let title = '';
  let error = '';
  if (r.code !== 0) {
    error = (r.error && (r.error.message || JSON.stringify(r.error))) || r.msg || 'cannot open';
  } else if (req.kind === 'wiki') {
    const node = data.node || {};
    title = node.title || '';
    if (node.obj_type === 'docx') docId = node.obj_token;
    else error = `wiki page is a ${node.obj_type}, only docs are read`;
  } else {
    docId = (data.document || {}).document_id || req.token;
    title = (data.document || {}).title || '';
  }
  return {
    json: {
      url: req.url,
      title,
      error,
      auth: req.auth,
      raw_url: `https://open.larksuite.com/open-apis/docx/v1/documents/${docId || 'missing'}/raw_content`,
    },
  };
});

const TZ = 'Asia/Ho_Chi_Minh';
// The NocoDB node nests a row as { id, id_fields, fields }.
const rowsOf = (name) => $(name).all()
  .map((i) => i.json || {})
  .filter((j) => j.id !== undefined && j.id !== null)
  .map((j) => ({ Id: j.id, ...(j.fields || {}) }));
const settingsOf = (name) => Object.fromEntries(
  rowsOf(name).filter((r) => r.key).map((r) => [r.key, (r.value ?? '').toString().trim()]));
const parseDt = (s) => DateTime.fromISO(String(s || '').trim().replace(' ', 'T'), { setZone: true }).setZone(TZ);
const parseDate = (s) => DateTime.fromISO(String(s || '').trim().slice(0, 10), { zone: TZ });
// settings.post_window, e.g. "07:00-22:00": the times posts may go out.
const windowOf = (v) => {
  const m = String(v || '').match(/(\d{1,2}):(\d{2})\s*-\s*(\d{1,2}):(\d{2})/);
  return m ? { from: `${m[1].padStart(2, '0')}:${m[2]}`, to: `${m[3].padStart(2, '0')}:${m[4]}` } : { from: '07:00', to: '22:00' };
};
const validTime = (t) => /^([01]\d|2[0-3]):[0-5]\d$/.test(t);
const slotOf = (dt) => { const h = Math.floor(dt.hour / 3) * 3; return `${String(h).padStart(2, '0')}-${String(h + 3).padStart(2, '0')}h`; };

const { settings, docs } = $('Read settings').first().json;
const warnings = docs.filter((d) => d.kind === 'unknown').map((d) => `Not a Lark doc or wiki link: ${d.url}`);
const parts = [];
if (settings.brand_brief) parts.push(`## Brand brief\n${settings.brand_brief}`);
if ($('Read doc').isExecuted) {
  const meta = $('Doc ids').all();
  $('Read doc').all().forEach((item, i) => {
    const m = meta[i].json;
    const r = item.json || {};
    if (m.error) warnings.push(`${m.url}: ${m.error}`);
    else if (r.code !== 0) warnings.push(`${m.url}: ${(r.error && r.error.message) || r.msg || 'cannot read'}`);
    else parts.push(`## ${m.title || m.url}\n${(r.data && r.data.content) || ''}`);
  });
}

const goals = rowsOf('Load goals');
const playbook = rowsOf('Load playbook');
const rank = { manager: 0, self: 1 };
const conf = { high: 0, medium: 1, low: 2 };
playbook.sort((a, b) => (rank[a.source] ?? 1) - (rank[b.source] ?? 1) || (conf[a.confidence] ?? 2) - (conf[b.confidence] ?? 2));
const guidelines = playbook.filter((l) => l.kind === 'guideline');
const lessons = playbook.filter((l) => l.kind !== 'guideline');
const log = rowsOf('Load work log').reverse();

return [{
  json: {
    settings,
    linked: Boolean(settings.lark_chat_id || settings.lark_open_id),
    brand: parts.join('\n\n').slice(0, 40000),
    warnings,
    goals_text: goals.map((g) => `#${g.Id} ${g.title} | metric ${g.metric} | target ${g.target ?? '?'} ${g.unit || ''} | due ${g.due_on || '-'}${g.notes ? ` | ${g.notes}` : ''}`).join('\n'),
    guidelines_text: guidelines.map((g) => `## #${g.Id} ${g.title} (${g.source === 'manager' ? 'from your manager' : 'yours'})\n${g.lesson}`).join('\n\n'),
    playbook_text: lessons.map((l) => `#${l.Id} [${l.source === 'manager' ? 'manager' : `self, ${l.confidence || 'low'}`}] [${l.category}] ${l.lesson}${l.source === 'manager' ? '' : ` (evidence: ${(l.evidence || '').slice(0, 200)})`}`).join('\n'),
    playbook_count: lessons.length,
    work_log_text: log.map((e) => `${parseDt(e.created_at).toFormat('dd/MM HH:mm')}: ${(e.text || '').slice(0, 600)}`).join('\n'),
    references_text: rowsOf('Load references').map((r) => `- ${r.hook}`).join('\n'),
    page_name: settings.page_name || 'the brand',
    language: settings.content_language || 'Vietnamese',
    post_window: windowOf(settings.post_window),
  },
}];
